import React, { useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { tours, filters } from '../data/mockData';
import SafeIcon from '../common/SafeIcon';
import { getDisplayTourBadge, getDisplayTourTitle, getPreviewMode, withPreviewMode } from '../utils/previewMode';

const colorMap = {
  orange: 'from-orange-900 via-orange-700 to-amber-500',
  emerald: 'from-emerald-900 via-emerald-700 to-lime-500',
  red: 'from-red-950 via-red-700 to-orange-400',
  blue: 'from-blue-950 via-blue-700 to-cyan-400',
  teal: 'from-teal-900 via-cyan-700 to-sky-400',
  purple: 'from-purple-950 via-purple-700 to-fuchsia-500'
};

function TourArt({ tour, compact = false, previewMode = 'reviewer' }) {
  const displayTitle = getDisplayTourTitle(tour, previewMode);
  const displayBadge = getDisplayTourBadge(tour, previewMode);

  return (
    <div className={`relative h-full w-full overflow-hidden bg-gradient-to-br ${colorMap[tour.color] || colorMap.orange}`}>
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_25%_20%,rgba(255,255,255,.35),transparent_28%),radial-gradient(circle_at_80%_65%,rgba(255,255,255,.2),transparent_30%)]" />
      <svg className="absolute inset-0 h-full w-full opacity-70" viewBox="0 0 100 100" preserveAspectRatio="none">
        <path d="M8 72 C24 44, 38 62, 52 38 S78 42, 92 18" fill="none" stroke="rgba(255,255,255,.72)" strokeWidth="2.5" strokeLinecap="round" strokeDasharray="4 4" />
        {[12, 35, 58, 82].map((x, i) => (
          <circle key={x} cx={x} cy={[68, 54, 42, 30][i]} r={compact ? 3 : 4} fill="white" stroke="rgba(15,23,42,.35)" strokeWidth="1" />
        ))}
      </svg>
      <div className="absolute bottom-3 left-3 right-3 rounded-2xl border border-white/20 bg-black/20 p-3 text-white backdrop-blur-sm">
        <p className="text-[10px] font-bold uppercase tracking-widest opacity-80">{displayBadge}</p>
        <p className="text-sm font-bold leading-tight" style={{ fontFamily: 'Georgia, serif' }}>{displayTitle}</p>
      </div>
    </div>
  );
}

export default function Catalog() {
  const [activeFilter, setActiveFilter] = useState('All');
  const navigate = useNavigate();
  const location = useLocation();
  const previewMode = getPreviewMode(location.search);
  const reviewerMode = previewMode === 'reviewer';
  const featured = tours[0];
  const japanFieldTours = tours.filter(tour => ['osaka-food-night', 'osaka-camera-crawl', 'kobe-kitano-harbor'].includes(tour.id));
  const secondary = tours.slice(1);
  const openRoute = (event, path) => {
    event.stopPropagation();
    navigate(withPreviewMode(path, location.search));
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      className="pb-24"
    >
      <div className="px-5 pt-4 pb-3 border-b border-slate-200/50">
        <div className="rounded-2xl bg-slate-900 p-4 text-white shadow-sm">
          <p className="text-[10px] font-bold uppercase tracking-widest text-orange-300">{reviewerMode ? 'PWA-first marketplace' : 'Local experiences'}</p>
          <h2 className="mt-1 text-xl font-bold" style={{ fontFamily: 'Georgia, serif' }}>Guided tours without an app install.</h2>
          <p className="mt-2 text-xs leading-relaxed text-slate-300">
            {reviewerMode ? 'Sell consumer tours, publish branded DMO packs, and capture high-signal local intent.' : 'Choose a walk, save it offline, and follow the story stop by stop.'}
          </p>
          <div className="mt-3 flex gap-2">
            <button onClick={() => navigate('/?mode=consumer')} className={`rounded-full px-3 py-1 text-[10px] font-bold uppercase ${previewMode === 'consumer' ? 'bg-white text-slate-900' : 'bg-white/10 text-slate-300'}`}>Consumer</button>
            <button onClick={() => navigate('/')} className={`rounded-full px-3 py-1 text-[10px] font-bold uppercase ${reviewerMode ? 'bg-orange-400 text-slate-950' : 'bg-white/10 text-slate-300'}`}>Reviewer</button>
          </div>
        </div>
      </div>

      <div className="overflow-x-auto hide-scrollbar px-5 py-4 flex gap-2 border-b border-slate-200/30">
        {filters.map(f => (
          <button
            key={f}
            onClick={() => setActiveFilter(f)}
            className={`whitespace-nowrap px-4 py-1.5 rounded-full text-sm font-medium transition-all ${
              activeFilter === f
                ? 'bg-slate-900 text-white shadow-md'
                : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
            }`}
          >
            {f}
          </button>
        ))}
      </div>

      <div className="p-5 space-y-8">
        <section className="rounded-3xl border border-red-100 bg-gradient-to-br from-red-50 to-orange-50 p-4 shadow-sm">
          <div className="flex items-start justify-between gap-3">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-widest text-red-700">Japan field test</p>
              <h2 className="mt-1 text-lg font-black text-slate-900">Osaka / Kobe this week</h2>
              <p className="mt-2 text-xs leading-relaxed text-red-950/80">
                Quick phone entry points for live walking tests: open Detail first to save the compact pack, then use Player in the field and Evidence after.
              </p>
            </div>
            <span className="rounded-full bg-white px-2 py-1 text-[10px] font-bold uppercase text-red-700">manual-first</span>
          </div>
          <div className="mt-4 space-y-3">
            {japanFieldTours.map(tour => (
              <div key={tour.id} className="rounded-2xl border border-white/70 bg-white/80 p-3 shadow-sm">
                <div className="mb-2 flex items-center justify-between gap-3">
                  <div>
                    <p className="text-xs font-black text-slate-900">{getDisplayTourTitle(tour, previewMode)}</p>
                    <p className="text-[10px] font-semibold text-slate-500">{tour.city} · {tour.stats || tour.subtitle}</p>
                  </div>
                  <span className="rounded-full bg-red-100 px-2 py-1 text-[9px] font-bold uppercase text-red-700">field</span>
                </div>
                <div className={`grid ${reviewerMode ? 'grid-cols-3' : 'grid-cols-2'} gap-2`}>
                  <button onClick={(event) => openRoute(event, `/tour/${tour.id}`)} className="rounded-xl bg-white py-2 text-[10px] font-bold uppercase tracking-widest text-slate-700 shadow-sm">Detail</button>
                  <button onClick={(event) => openRoute(event, `/player/${tour.id}`)} className="rounded-xl bg-slate-900 py-2 text-[10px] font-bold uppercase tracking-widest text-white shadow-sm">Player</button>
                  {reviewerMode && <button onClick={(event) => openRoute(event, `/evidence/${tour.id}`)} className="rounded-xl bg-blue-50 py-2 text-[10px] font-bold uppercase tracking-widest text-blue-700 shadow-sm">Evidence</button>}
                </div>
              </div>
            ))}
          </div>
        </section>

        {reviewerMode && (
          <section className="rounded-3xl border border-orange-100 bg-orange-50 p-4 shadow-sm">
            <div className="flex items-start justify-between gap-3">
              <div>
                <p className="text-[10px] font-bold uppercase tracking-widest text-orange-700">Reviewer mode</p>
                <h2 className="mt-1 text-lg font-black text-slate-900">Start with the local proof loop.</h2>
                <p className="mt-2 text-xs leading-relaxed text-orange-950/80">
                  Synthetic/local demo only: seed evidence, test the player offer + loyalty loop, then inspect the partner field-test console.
                </p>
              </div>
              <span className="rounded-full bg-white px-2 py-1 text-[10px] font-bold uppercase text-orange-700">no live infra</span>
            </div>
            <div className="mt-4 grid grid-cols-3 gap-2">
              <button onClick={(event) => openRoute(event, '/evidence/portland-screen')} className="rounded-xl bg-orange-700 py-3 text-[10px] font-bold uppercase tracking-widest text-white shadow-sm">Evidence</button>
              <button onClick={(event) => openRoute(event, '/player/portland-screen')} className="rounded-xl bg-slate-900 py-3 text-[10px] font-bold uppercase tracking-widest text-white shadow-sm">Player</button>
              <button onClick={(event) => openRoute(event, '/b2b')} className="rounded-xl bg-white py-3 text-[10px] font-bold uppercase tracking-widest text-slate-700 shadow-sm">Partner</button>
            </div>
          </section>
        )}

        <section>
          <h2 className="text-sm font-bold uppercase tracking-widest text-slate-500 mb-4">Featured Tour Pack</h2>
          <div
            onClick={() => navigate(withPreviewMode(`/tour/${featured.id}`, location.search))}
            className="group relative bg-white rounded-3xl overflow-hidden shadow-sm border border-slate-100 cursor-pointer active:scale-[0.98] transition-transform"
          >
            <div className="h-64 relative">
              <TourArt tour={featured} previewMode={previewMode} />
              <div className="absolute top-4 left-4 flex gap-2">
                <span className="bg-white/90 backdrop-blur text-slate-900 text-xs font-bold px-3 py-1 rounded-full shadow-sm">
                  {getDisplayTourBadge(featured, previewMode)}
                </span>
                <span className="bg-emerald-100/95 backdrop-blur text-emerald-900 text-xs font-bold px-3 py-1 rounded-full shadow-sm">
                  Offline ready
                </span>
              </div>
              <div className="absolute top-4 right-4">
                <span className="bg-orange-500/95 backdrop-blur text-white text-[10px] uppercase tracking-wider font-bold px-2 py-1 rounded shadow-sm flex items-center gap-1">
                  <SafeIcon name="Award" className="w-3 h-3" />
                  {featured.partner}
                </span>
              </div>
            </div>
            <div className="space-y-3 bg-white px-5 py-4">
              <div className="flex items-center justify-between">
                <div className="flex gap-2 flex-wrap">
                  {featured.tags.map(tag => (
                    <span key={tag} className="text-xs font-medium text-slate-500 bg-slate-100 px-2.5 py-1 rounded-md">
                      {tag}
                    </span>
                  ))}
                </div>
                <SafeIcon name="ArrowRight" className="w-5 h-5 text-slate-400 group-hover:text-slate-900 transition-colors" />
              </div>
              <div className={`grid ${reviewerMode ? 'grid-cols-3' : 'grid-cols-2'} gap-2`}>
                <button onClick={(event) => openRoute(event, `/tour/${featured.id}`)} className="rounded-xl bg-slate-100 py-2 text-[10px] font-bold uppercase tracking-widest text-slate-700">Detail</button>
                <button onClick={(event) => openRoute(event, `/player/${featured.id}`)} className="rounded-xl bg-slate-900 py-2 text-[10px] font-bold uppercase tracking-widest text-white">Player</button>
                {reviewerMode && <button onClick={(event) => openRoute(event, `/evidence/${featured.id}`)} className="rounded-xl bg-blue-50 py-2 text-[10px] font-bold uppercase tracking-widest text-blue-700">Evidence</button>}
              </div>
            </div>
          </div>
        </section>

        <section>
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-sm font-bold uppercase tracking-widest text-slate-500">More Experiences</h2>
            <button onClick={() => navigate('/b2b')} className="text-xs font-bold text-orange-700">For partners</button>
          </div>
          <div className="grid grid-cols-1 gap-4">
            {secondary.map(tour => (
              <div
                key={tour.id}
                onClick={() => navigate(withPreviewMode(`/tour/${tour.id}`, location.search))}
                className="flex bg-white rounded-2xl overflow-hidden shadow-sm border border-slate-100 cursor-pointer active:scale-[0.98] transition-transform p-3 gap-4 items-center"
              >
                <div className="w-24 h-24 rounded-xl overflow-hidden flex-shrink-0 relative">
                  <TourArt tour={tour} compact previewMode={previewMode} />
                </div>
                <div className="flex-1 min-w-0 py-1">
                  <p className="text-[10px] font-bold uppercase tracking-wider mb-1 text-slate-500">
                    {tour.subtitle}
                  </p>
                  <h3 className="text-base font-bold text-slate-900 truncate" style={{ fontFamily: 'Georgia, serif' }}>{getDisplayTourTitle(tour, previewMode)}</h3>
                  <p className="text-xs text-slate-500 mt-1">{tour.city}</p>
                  <div className="mt-2 flex items-center gap-2">
                    <span className="text-xs font-bold text-slate-900 bg-slate-100 px-2 py-0.5 rounded">
                      {getDisplayTourBadge(tour, previewMode)}
                    </span>
                    {reviewerMode && <span className="text-[10px] text-slate-500 truncate">{tour.packId}</span>}
                  </div>
                  <div className={`mt-3 grid ${reviewerMode ? 'grid-cols-3' : 'grid-cols-2'} gap-1.5`}>
                    <button onClick={(event) => openRoute(event, `/tour/${tour.id}`)} className="rounded-lg bg-slate-100 py-1.5 text-[9px] font-bold uppercase tracking-widest text-slate-700">Detail</button>
                    <button onClick={(event) => openRoute(event, `/player/${tour.id}`)} className="rounded-lg bg-slate-900 py-1.5 text-[9px] font-bold uppercase tracking-widest text-white">Player</button>
                    {reviewerMode && <button onClick={(event) => openRoute(event, `/evidence/${tour.id}`)} className="rounded-lg bg-blue-50 py-1.5 text-[9px] font-bold uppercase tracking-widest text-blue-700">Evidence</button>}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>
    </motion.div>
  );
}
